// the same dark ground as index.html's first frame, so a page still loading its code doesn't flash white
const PageFallback = () => <div className="min-h-screen bg-[#12161f]" />;

/**
 * SmartAdvisor mounting is deferred until the user interacts (mouse/touch/scroll/key)
 * or 5 seconds elapse — whichever comes first. This keeps the initial JS bundle small
 * and improves INP / TBT on mobile.
 */
const DeferredSmartAdvisor = () => {
  const [shouldMount, setShouldMount] = useState(false);

  useEffect(() => {
    if (shouldMount) return;

    let timeoutId: ReturnType<typeof setTimeout>;
    const mount = () => setShouldMount(true);

    const events: (keyof WindowEventMap)[] = ['mousemove', 'touchstart', 'scroll', 'keydown', 'click'];
    events.forEach((evt) => window.addEventListener(evt, mount, { once: true, passive: true } as any));

    // Fallback: mount after 5s even without interaction so the icon appears
    timeoutId = setTimeout(mount, 5000);

    return () => {
      clearTimeout(timeoutId);
      events.forEach((evt) => window.removeEventListener(evt, mount));
    };
  }, [shouldMount]);

  if (!shouldMount) return null;

  return (
    <Suspense fallback={null}>
      <SmartAdvisor />
    </Suspense>
  );
};

/**
 * AccessibilityWidget is deferred 2s after initial load — it's never in the
 * initial viewport and shouldn't compete with hero rendering.
 */
const DeferredAccessibilityWidget = () => {
  const [shouldMount, setShouldMount] = useState(false);

  useEffect(() => {
    const t = setTimeout(() => setShouldMount(true), 2000);
    return () => clearTimeout(t);
  }, []);

  if (!shouldMount) return null;

  return (
    <Suspense fallback={null}>
      <AccessibilityWidget />
    </Suspense>
  );
};

